"""Saved-record inspection with explicit fixture/missingness labels; no actor effects."""
import html,json
from pathlib import Path

def render(root):
 root=Path(root);m=json.loads((root/'manifest.json').read_text());s=json.loads((root/'summary.json').read_text());items=[]
 for a,r in zip(m['assignments'],s['results']):
  f=root/'calls'/(a['id']+'-finished.json');result=json.loads(f.read_text()) if f.exists() else {'error':'not_completed','value':None}
  items.append({'assignment':a,'scoring':r,'result':result})
 body='''<!doctype html><meta charset="utf-8"><title>Theseus D1 diagnostic evidence</title><style>body{max-width:1100px;margin:36px auto;padding:16px;background:#11202b;color:#edf6fc;font:16px system-ui}select{padding:12px;max-width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#20333f;padding:18px}table{border-collapse:collapse}td,th{padding:8px;border:1px solid #738591}</style><h1>Theseus D1 execution diagnostic</h1><p id="status"></p><p>Dispatch order is an execution log, not a cultural timeline. Evaluator truth is shown only to the viewer. Missing/invalid outputs remain in assigned denominators.</p><details><summary>All world/context/arm cells (expand)</summary><table><thead><tr><th>World / context / arm</th><th>Correct / assigned</th><th>Valid response decisions</th></tr></thead><tbody id="cells"></tbody></table></details><h2>Inspect a recorded call</h2><label>Assignment <select id="pick"></select></label><p id="outcome"></p><h3>Visible cases and supplied mapping</h3><pre id="cases"></pre><h3>Saved output and scorer result</h3><pre id="result"></pre><script>const DATA=__DATA__;const S=__SUMMARY__;document.getElementById('status').textContent=S.status+' — '+S.completed_call_records+'/'+S.assigned_calls+' call records, '+S.assigned_decisions+' assigned decisions';for(const [k,v] of Object.entries(S.cells)){let tr=document.createElement('tr');for(const x of [k,v.correct+'/'+v.assigned,v.valid_response_decisions]){let td=document.createElement('td');td.textContent=x;tr.append(td)}document.getElementById('cells').append(tr)}let pick=document.getElementById('pick');DATA.forEach((x,i)=>{let o=document.createElement('option');o.value=i;o.textContent=x.assignment.id;pick.append(o)});function draw(){let x=DATA[+pick.value];document.getElementById('cases').textContent=JSON.stringify({rule:x.assignment.rule,cases:x.assignment.cases},null,2);document.getElementById('result').textContent=JSON.stringify({raw:x.result,scoring:x.scoring},null,2);document.getElementById('outcome').textContent=x.scoring.errors.length?'Invalid/missing: '+x.scoring.errors.join(', '):'Valid response; inspect correctness below'}pick.onchange=draw;draw();</script>'''
 body=body.replace('__DATA__',json.dumps(items).replace('<','\\u003c')).replace('__SUMMARY__',json.dumps(s).replace('<','\\u003c'))
 (root/'replay.html').write_text(body)
